import json
from lib import *
R = J('r120'); v = R['var']; ks = R['keyspace']; sz = {int(k): x for k, x in R['size'].items()}; pc = R['pc']
KV = lambda items, hl=(): {'items': items, 'hl': list(hl)}
def bars(items, mx, cur=(), mark=(), done=()): return {'items': items, 'max': mx, 'cur': list(cur), 'mark': list(mark), 'done': list(done)}
def tm(lines, cur=(), mark=()): return {'lines': lines, 'cur': list(cur), 'mark': list(mark)}
steps = [
    step(f"同一个配置(SET、50 连接、20 万次)连续跑 5 次:{'、'.join(f'{x/1000:.0f}k' for x in v)} 条/秒,最大/最小 = {max(v)/min(v):.2f}。单次压测有约 ±10% 的波动,所以差 10% 以内的对比没有意义,要多跑几次取中位。", b=bars([[f'第 {i+1} 次', x / 1000, f'{x/1000:.0f}k'] for i, x in enumerate(v)], max(v) / 1000, done=range(5)), kv=KV([['波动', f'最大/最小 {max(v)/min(v):.2f}']], ['波动'])),
    step(f"陷阱一:redis-benchmark 默认所有请求打同一个 key。跑完 100 万次 SET,DBSIZE = {ks['k1']}、used_memory {ks['m1']/1e6:.1f} MB——你没有测到「有数据的 Redis」。加 -r 1000000 让 key 随机:DBSIZE = {ks['k2']}、used_memory {ks['m2']/1e6:.0f} MB。有意思的是两种情形吞吐都是约 {ks['same']/1000:.0f}k/s(这个负载受往返限制,内存大小没有影响吞吐),但换成真实的数据量,缓存命中、淘汰、fork 的表现都会不同。", b=bars([['默认:DBSIZE', ks['k1'] / 1000, str(ks['k1'])], ['-r 1000000:DBSIZE', ks['k2'] / 1000, str(ks['k2'])]], ks['k2'] / 1000, mark=[0], done=[1]), kv=KV([['DBSIZE', f"{ks['k1']} vs {ks['k2']}"], ['used_memory', f"{ks['m1']/1e6:.1f} vs {ks['m2']/1e6:.0f} MB"]], ['DBSIZE'])),
    step(f"陷阱二:value 大小。SET 3 / 100 / 1024 / 10240 / 102400 字节:{sz[3]/1000:.0f}k / {sz[100]/1000:.0f}k / {sz[1024]/1000:.0f}k / {sz[10240]/1000:.0f}k / {sz[102400]/1000:.0f}k 条/秒。前三档几乎一样,10 KB 起才明显下降,100 KB 只有 3 KB 时的 {sz[102400]/sz[3]*100:.0f}%。默认的 3 字节 value 测出来的数字对大 value 业务没有参考价值。", b=bars([[f'{d} 字节', sz[d] / 1000, f'{sz[d]/1000:.0f}k/s'] for d in (3, 100, 1024, 10240, 102400)], sz[3] / 1000, mark=[4], done=[0, 1, 2]), kv=KV([['3 → 100 KB', f'{sz[3]/1000:.0f}k → {sz[102400]/1000:.0f}k /s']], ['3 → 100 KB'])),
    step(f"陷阱三:连接数与管道。GET、无管道:1 个连接 {pc['1_1']/1000:.0f}k、10 个连接 {pc['1_10']/1000:.0f}k、50 个 {pc['1_50']/1000:.0f}k、500 个 {pc['1_500']/1000:.0f}k——1 个连接是往返限制,10 个以上就到平台。管道 16 后:{pc['16_1']/1000:.0f}k / {pc['16_10']/1000:.0f}k / {pc['16_50']/1000:.0f}k / {pc['16_500']/1000:.0f}k。同一个 Redis,数字能差 {pc['16_10']/pc['1_1']:.0f} 倍。", b=bars([['P=1 c=1', pc['1_1'] / 1000, f"{pc['1_1']/1000:.0f}k"], ['P=1 c=10', pc['1_10'] / 1000, f"{pc['1_10']/1000:.0f}k"], ['P=16 c=1', pc['16_1'] / 1000, f"{pc['16_1']/1000:.0f}k"], ['P=16 c=10', pc['16_10'] / 1000, f"{pc['16_10']/1000:.0f}k"]], pc['16_10'] / 1000, mark=[0], done=[3]), kv=KV([['倍数', f"{pc['16_10']/pc['1_1']:.0f}×"]], ['倍数'])),
    step("陷阱四:压测机与被测机同一台。本文所有数字都是本机回环:压测程序与 Redis 抢同一批 CPU,而且没有真实网络。所以这些数字只能用来「比较配置」,不能当作「这台机器的 Redis 能跑多少」。", t=tm(['redis-benchmark ⇄ redis-server(同一台机器,回环)'], mark=[0]), kv=KV([['结论', '数字只用于相对比较']], ['结论'])),
]
A = dict(
    n=120, series='redis', tags='Redis,Benchmark,压测,真实验证,动画演示',
    desc=f'用 redis-benchmark 量出四个常见陷阱:同一配置 5 次波动 ±{(max(v)/min(v)-1)*100:.0f}%;默认只打同一个 key(DBSIZE = {ks["k1"]}、内存 {ks["m1"]/1e6:.1f} MB,-r 才有数据);value 3 → 100 KB 吞吐 {sz[3]/1000:.0f}k → {sz[102400]/1000:.0f}k;连接数与管道让同一个 Redis 的数字差 {pc["16_10"]/pc["1_1"]:.0f} 倍({pc["1_1"]/1000:.0f}k → {pc["16_10"]/1000:.0f}k)。',
    lead='压测数字最容易骗人。redis-benchmark 默认的参数几乎每一项都不像真实业务。这篇不追求「测出一个漂亮的数」,而是把默认参数下容易踩的坑各量一遍:波动、key 空间、value 大小、连接与管道、以及压测机的位置。',
    facts=[(f'±{(max(v)/min(v)-1)*100:.0f}%', '同一配置连续 5 次的波动(最大/最小 %.2f)' % (max(v) / min(v))), (f'{pc["16_10"]/pc["1_1"]:.0f} 倍', f'同一个 Redis:1 个连接无管道 {pc["1_1"]/1000:.0f}k vs 10 个连接管道 16 {pc["16_10"]/1000:.0f}k 条/秒'), (f'{sz[102400]/sz[3]*100:.0f}%', '100 KB value 的 SET 吞吐相对 3 字节的比例')],
    body=[
        sec('结果的波动', '', term('', blk('r120', 1)), f'<p>同一个命令连续 5 次:{"、".join(f"{x/1000:.0f}k" for x in v)},最大/最小 {max(v)/min(v):.2f}。差别小于这个范围的对比都可能只是噪声。</p>'),
        sec('key 空间', '', term('', blk('r120', 2)), f'<p>默认情况下 redis-benchmark 的所有请求打同一个 key(<code>key:__rand_int__</code> 在没有 <code>-r</code> 时是同一个),跑完 100 万次 SET 库里只有 {ks["k1"]} 个 key、{ks["m1"]/1e6:.1f} MB。<code>-r 1000000</code> 才会用随机 key(跑完 {ks["k2"]} 个、{ks["m2"]/1e6:.0f} MB)。本机这个无管道的负载里两者吞吐一样,但依赖数据量的现象(命中率、淘汰、fork、RDB/AOF)在「一个 key」的测试里根本不会出现。</p>'),
        sec('value 大小', '为避免占满内存,这一组用 -r 1000 限制 key 数', term('', blk('r120', 3)), f'<p>3、100、1024 字节的 value 吞吐几乎一样({sz[3]/1000:.0f}k、{sz[100]/1000:.0f}k、{sz[1024]/1000:.0f}k),10 KB 降到 {sz[10240]/1000:.0f}k,100 KB 只有 {sz[102400]/1000:.0f}k。默认 3 字节 value 测不到大 value 下的行为。(我第一次把这组和 <code>-r 100000</code> 一起跑,结果是 100 KB × 10 万个 key = 近 10 GB,把机器压进了交换,实验被我中止后重做;这也是一个「压测会把机器压垮」的真实例子。)</p>'),
        sec('连接数与管道', '', term('', blk('r120', 4)), f'<p>无管道时 1 个连接受往返限制({pc["1_1"]/1000:.0f}k),10 个连接以上到平台({pc["1_10"]/1000:.0f}k);管道 16 后平台是 {pc["16_10"]/1000:.0f}k,再多连接(500)略降到 {pc["16_500"]/1000:.0f}k。选哪一种要看你的业务真实是什么样:一个连接同步请求的业务和大批量导入的业务,数字差一个数量级。</p>'),
        sec('压测机的位置', '', '<p>这篇的所有数字都是同一台机器、回环网络、压测程序与 Redis 抢 CPU。它们只能用来比较配置,不能当作容量规划的依据;容量规划要用独立的压测机、真实网络,并且用接近真实的命令组合与 key/value 分布(第 121 篇)。</p>'),
        sec('分步演示:五个陷阱', '', demo('Redis Benchmark 的常见陷阱', [('b', 'bars', '数据'), ('t', 'term', '说明'), ('kv', 'kv', '要点')], steps, '本步的对象')),
    ],
    refs=[ENV_R + '。redis-benchmark 8.10.2 -q;每格 3 次取中位(第一组是 5 次原始值);本机 10 核,同机压测', '没有验证:独立压测机、真实网卡、多个 redis-benchmark 进程叠加、开启持久化/复制后的数字、TLS 下的压测'],
)
